","interface StoreMetrics {
 healthy: number;
 watch: number;
 at_risk: number;
 critical: number;
 total: number;
}

const headers = {
 Accept: 'application/json',
 'X-UserToken': (window as any).g_ck,
};

export async function getStoreMetrics(): Promise<StoreMetrics> {
 const url =
 '/api/now/stats/x_2145749_qc_dark_store?sysparm_count=true&sysparm_group_by=pulse_score_band&sysparm_query=status=active';
 const res = await fetch(url, { headers });
 const data = await res.json();

 const metrics: StoreMetrics = { healthy: 0, watch: 0, at_risk: 0, critical: 0, total: 0 };

 if (data.result) {
 for (const group of data.result) {
 const band = group.groupby_fields?.[0]?.value || '';
 const count = parseInt(group.stats?.count || '0', 10);
 if (band in metrics) {
 metrics[band as keyof Omit<StoreMetrics, 'total'>] = count;
 }
 metrics.total += count;
 }
 }

 return metrics;
}

export async function getAlertCounts(): Promise<number> {
 const url =
 '/api/now/stats/x_2145749_qc_store_issue?sysparm_count=true&sysparm_query=state!=closed';
 const res = await fetch(url, { headers });
 const data = await res.json();
 return parseInt(data.result?.stats?.count || '0', 10);
}
","export default function insertStyle(css, tagName = "style") {
