 color: rgb(var(--now-color--text--secondary, 109, 109, 109));
}

.metric-card__indicator {
 width: 10px;
 height: 10px;
 border-radius: 50%;
 display: inline-block;
 margin-right: 6px;
}

.metric-card__indicator--healthy { background: rgb(var(--now-color--alert--positive--1, 61, 133, 1)); }
.metric-card__indicator--watch { background: rgb(var(--now-color--alert--warning--1, 196, 127, 0)); }
.metric-card__indicator--at_risk { background: rgb(var(--now-color--alert--high--1, 209, 92, 0)); }
.metric-card__indicator--critical { background: rgb(var(--now-color--alert--critical--1, 200, 16, 0)); }
.metric-card__indicator--total { background: rgb(var(--now-color--text--primary, 41, 41, 41)); }
