",".ops-dashboard {
 padding: 24px;
 max-width: 1400px;
 margin: 0 auto;
 font-family: var(--now-font-family, 'Source Sans Pro', Arial, sans-serif);
}

.ops-dashboard__header {
 margin-bottom: 24px;
}

.ops-dashboard__title {
 font-size: 28px;
 font-weight: 600;
 color: rgb(var(--now-color--text--primary, 41, 41, 41));
 margin: 0 0 4px 0;
}

.ops-dashboard__subtitle {
 font-size: 14px;
 color: rgb(var(--now-color--text--secondary, 109, 109, 109));
 margin: 0;
}

.ops-dashboard__content {
 margin-top: 24px;
}
","import React, { useState } from 'react';
import { Tabs } from '@servicenow/react-components/Tabs';
import MetricCards from './components/MetricCards';
import StoreList from './components/StoreList';
import IssueList from './components/IssueList';
import IncidentList from './components/IncidentList';
import './app.css';

const tabItems = [
 { id: 'stores', label: 'Dark Stores' },
 { id: 'issues', label: 'Store Issues' },
 { id: 'incidents', label: 'Partner Incidents' },
];

export default function App() {
 const [activeTab, setActiveTab] = useState('stores');

 return (
 <div className="ops-dashboard">
 <div className="ops-dashboard__header">
 <h1 className="ops-dashboard__title">Quick Commerce Operations</h1>
 <p className="ops-dashboard__subtitle">
 Dark Store Health &amp; Incident Management
 </p>
 </div>
 <MetricCards />
 <div className="ops-dashboard__content">
 <Tabs
 items={tabItems}
 selectedItem={activeTab}
 onSelectedItemSet={(e: any) => setActiveTab(e.detail.value)}
 />
 {activeTab === 'stores' && <StoreList />}
 {activeTab === 'issues' && <IssueList />}
 {activeTab === 'incidents' && <IncidentList />}
 </div>
 </div>
 );
}
